/// Maximum RIFSC peripheral ID for `stm32mp21xxxx`.
pub const RIFSC_ID_MAX: u8 = 127;

/// Look up a [`RifEntry`] by RIFSC ID.
pub fn lookup(id: u8) -> Option<RifEntry> {
    ALL_PERIPHERALS.iter().copied().find(|e| e.id as u8 == id)
}
